INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-001','https://www.prothomalo.com/bangladesh/district/15o1rzfiv8',NULL,'{"type":"News","source":"Prothom Alo","title":"ছোট যমুনা থেকে বালু লুট","date":"2022-11-14","dateKind":"Published","district":"Naogaon","river":"Chhoto Jamuna; Badalgachhi; Tejapara","material":"Sand; soil","topics":"Extraction; erosion; livelihoods; complaints","language":"Bangla","en":"Residents alleged extraction outside leased areas near Tejapara, threatening farmland and an embankment. The report describes protests, disputed accusations, and an investigation ordered by the local administration.","bn":"তেজাপাড়ায় ইজারার সীমানার বাইরে বালু ও মাটি উত্তোলনে কৃষিজমি ও বাঁধ ঝুঁকিতে পড়ার অভিযোগ উঠে। প্রতিবেদনে প্রতিবাদ, পাল্টাপাল্টি অভিযোগ এবং প্রশাসনের তদন্তের নির্দেশের কথা রয়েছে।","evidence":"Article text","flag":"Verify allegations","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/15o1rzfiv8","alternateUrl":"","notes":"Statements of residents, lease operators and officials are reported claims. Do not classify legality from the headline alone.","id":"BSW-001","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:04.824Z"}','2026-10-11T22:32:04.824Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-002','https://www.thedailystar.net/news/bangladesh/news/illegal-sand-extraction-teesta-continues-4217606',NULL,'{"type":"News","source":"The Daily Star","title":"Illegal sand extraction from Teesta continues","date":"2026-07-06","dateKind":"Updated","district":"Lalmonirhat","river":"Teesta; Kaliganj; Hatibandha; Lalmonirhat Sadar","material":"Sand","topics":"Extraction; enforcement; erosion","language":"English","en":"The report describes continued dredger extraction along the Teesta despite enforcement drives. Residents alleged erosion and intimidation; officials described equipment seizure and difficulties filing cases when operators were absent.","bn":"অভিযানের পরও তিস্তায় ড্রেজার দিয়ে বালু উত্তোলন চলার কথা প্রতিবেদনে বলা হয়েছে। স্থানীয়রা ভাঙন ও ভয়ভীতির অভিযোগ করেন। কর্মকর্তারা যন্ত্র জব্দ এবং অভিযুক্তদের অনুপস্থিতিতে মামলা করার সমস্যার কথা জানান।","evidence":"Article text","flag":"Verify allegations","documentId":"","otherDate":"","url":"https://www.thedailystar.net/news/bangladesh/news/illegal-sand-extraction-teesta-continues-4217606","alternateUrl":"","notes":"Page provides an update date, not a separately verified original publication date. Separate from BSW-006: different river reach and reported incident.","id":"BSW-002","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:04.920Z"}','2026-10-11T22:32:04.920Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-003','https://bengali.mongabay.com/2022/08/16/%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81%E0%A6%B0-%E0%A6%AC%E0%A6%BE%E0%A6%A1%E0%A6%BC%E0%A6%A4%E0%A6%BF-%E0%A6%9A%E0%A6%BE%E0%A6%B9%E0%A6%BF%E0%A6%A6%E0%A6%BE-%E0%A6%AE%E0%A7%87%E0%A6%9F%E0%A6%BE/',NULL,'{"type":"News","source":"Mongabay Bangla","title":"বালুর বাড়তি চাহিদা মেটাতে নদীতে অবৈধ উত্তোলন, বিপর্যয়ে বাংলাদেশের প্রতিবেশ","date":"2022-08-16","dateKind":"Published","district":"Multiple; national","river":"Bangladesh river systems","material":"Sand","topics":"Demand; governance; environmental impacts","language":"Bangla","en":"This feature links construction demand with river sand extraction and reports environmental and governance concerns. It combines stakeholder accounts and national context rather than documenting one extraction incident.","bn":"ফিচারটি নির্মাণশিল্পের চাহিদার সঙ্গে নদী থেকে বালু উত্তোলনের সম্পর্ক তুলে ধরে। এতে পরিবেশ ও ব্যবস্থাপনার সমস্যা নিয়ে বিভিন্ন পক্ষের বক্তব্য রয়েছে। এটি একটি নির্দিষ্ট ঘটনার বদলে জাতীয় প্রেক্ষাপট আলোচনা করে।","evidence":"Article text","flag":"Check estimates","documentId":"","otherDate":"2025-10-01","url":"https://bengali.mongabay.com/2022/08/16/%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81%E0%A6%B0-%E0%A6%AC%E0%A6%BE%E0%A6%A1%E0%A6%BC%E0%A6%A4%E0%A6%BF-%E0%A6%9A%E0%A6%BE%E0%A6%B9%E0%A6%BF%E0%A6%A6%E0%A6%BE-%E0%A6%AE%E0%A7%87%E0%A6%9F%E0%A6%BE/","alternateUrl":"","notes":"Keep 2022 publication separate from 2025 modification. National quantities and legal/illegal shares need separate evidence before reuse as measured statistics.","id":"BSW-003","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.022Z"}','2026-10-11T22:32:05.022Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-004','https://www.prothomalo.com/bangladesh/district/t6xo2rj5qz',NULL,'{"type":"News","source":"Prothom Alo","title":"সিলেটে পাথর কোয়ারি ইজারা না দেওয়ার সরকারি সিদ্ধান্ত বহাল রাখার দাবি","date":"2025-06-26","dateKind":"Published","district":"Sylhet","river":"Sylhet stone quarries; Jaflong","material":"Stone; gravel","topics":"Quarrying; civil society; court orders; policy","language":"Bangla","en":"A coalition convened through BELA urged retention of restrictions on stone quarry leasing and extraction in Sylhet. The article reports advocacy positions and concerns about machinery, protected areas, air pollution, and noise.","bn":"বেলার উদ্যোগে গঠিত জোট সিলেটে পাথর কোয়ারি ইজারা ও উত্তোলনের ওপর বিধিনিষেধ বহাল রাখার দাবি জানায়। প্রতিবেদনে যন্ত্রের ব্যবহার, সংরক্ষিত এলাকা এবং বায়ু ও শব্দদূষণ নিয়ে উদ্বেগ তুলে ধরা হয়।","evidence":"Article text","flag":"Verify legal references","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/t6xo2rj5qz","alternateUrl":"","notes":"An advocacy meeting is distinct from an official directive. Verify the cited orders before assigning legal status.","id":"BSW-004","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.138Z"}','2026-10-11T22:32:05.138Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-005','https://www.bonikbarta.com/bangladesh/Z5nbIS39Gs5OfNpC/',NULL,'{"type":"News","source":"Bonik Barta","title":"সিলেটের তিন কোয়ারি থেকে পাথর উত্তোলনের অনুমতি","date":"2021-01-26","dateKind":"Published","district":"Sylhet","river":"Jaflong; Bholaganj; Bichhanakandi","material":"Stone; gravel","topics":"Quarrying; court orders; restrictions","language":"Bangla","en":"The article reports a temporary court suspension of extraction restrictions at three Sylhet quarries, with conditions on machinery and protected areas. It also describes environmental concerns and earlier restrictions.","bn":"প্রতিবেদনে সিলেটের তিনটি কোয়ারিতে উত্তোলনের নিষেধাজ্ঞা আদালত সাময়িকভাবে স্থগিত করার কথা বলা হয়েছে। যন্ত্র ও সংরক্ষিত এলাকা নিয়ে শর্ত, পরিবেশগত উদ্বেগ এবং আগের বিধিনিষেধও উল্লেখ রয়েছে।","evidence":"Article text; spacing errors","flag":"Verify legal references","documentId":"","otherDate":"","url":"https://www.bonikbarta.com/bangladesh/Z5nbIS39Gs5OfNpC/","alternateUrl":"","notes":"Historical report, not current permission. Scrape collapses word spacing in parts of the body. Canonical URL taken from page metadata/share links.","id":"BSW-005","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.229Z"}','2026-10-11T22:32:05.229Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-006','https://observerbd.com/news/582009',NULL,'{"type":"News","source":"Daily Observer","title":"Flood fears loom as Buri Teesta dam cracks a year after renovation","date":"2026-07-05","dateKind":"Published","district":"Nilphamari","river":"Buri Teesta; Jaldhaka; Gholmunda; Dauabari","material":"Sand","topics":"Extraction; transport; embankment damage","language":"English","en":"Residents linked embankment cracks and subsidence to alleged illegal extraction and overloaded sand transport. Local officials acknowledged transport damage. The article also raises concerns about construction quality and repair needs.","bn":"স্থানীয়রা বাঁধের ফাটল ও ধসের সঙ্গে অবৈধ বালু উত্তোলন ও অতিরিক্ত বোঝাই পরিবহনকে যুক্ত করেন। কর্মকর্তারাও পরিবহনের ক্ষতির কথা স্বীকার করেন। নির্মাণের মান ও মেরামতের প্রয়োজন নিয়েও প্রশ্ন ওঠে।","evidence":"Article text","flag":"Check chronology","documentId":"","otherDate":"","url":"https://observerbd.com/news/582009","alternateUrl":"","notes":"Headline says renovation was a year earlier, while the body says the project ended in 2023. Preserve this inconsistency. Do not merge with BSW-002 solely because both mention Teesta.","id":"BSW-006","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.323Z"}','2026-10-11T22:32:05.323Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-007','https://www.tbsnews.net/features/panorama/saving-shomeshwari-ecology-economy-and-true-cost-sand-1318481',NULL,'{"type":"News","source":"The Business Standard","title":"Saving Shomeshwari: Ecology, economy, and the true cost of sand","date":"2025-12-25","dateKind":"Published","district":"Netrokona","river":"Someshwari / Shomeshwari; Durgapur; Birishiri","material":"Sand; stone","topics":"Extraction suspension; reported recovery; livelihoods","language":"English","en":"This feature describes residents'' accounts of reduced extraction, returning fishing activity, and economic pressure after a reported suspension. It also reports concerns about nighttime extraction and future policy changes.","bn":"উত্তোলন স্থগিত থাকার পর খনন কমা, মাছ ধরার তৎপরতা ফেরা এবং অর্থনৈতিক চাপ নিয়ে স্থানীয়দের অভিজ্ঞতা ফিচারটিতে তুলে ধরা হয়েছে। রাতে উত্তোলন ও ভবিষ্যৎ নীতিগত পরিবর্তন নিয়েও উদ্বেগ রয়েছে।","evidence":"Article text","flag":"Verify recovery claims","documentId":"","otherDate":"2026-06-25","url":"https://www.tbsnews.net/features/panorama/saving-shomeshwari-ecology-economy-and-true-cost-sand-1318481","alternateUrl":"","notes":"Reported recovery is not a measured ecological trend. Verify the court order and suspension dates. Normalize Shomeshwari and Someshwari as aliases without changing the original title.","id":"BSW-007","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.411Z"}','2026-10-11T22:32:05.411Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-008','https://www.thedailystar.net/opinion/editorial/news/why-cant-we-stop-illegal-sand-mining-4017971',NULL,'{"type":"Editorial","source":"The Daily Star","title":"Why can’t we stop illegal sand mining?","date":"2025-10-25","dateKind":"Updated","district":"Munshiganj; Narayanganj; others","river":"Meghna and other rivers","material":"Sand","topics":"Enforcement; political influence; governance","language":"English","en":"The editorial discusses reported extraction outside licensed areas and argues for stronger enforcement, lease cancellation, accountability, and interagency coordination. Its recommendations and interpretations should remain labeled as editorial opinion.","bn":"সম্পাদকীয়টি ইজারার সীমানার বাইরে উত্তোলনের খবর আলোচনা করে কঠোর প্রয়োগ, ইজারা বাতিল, জবাবদিহি ও আন্তঃসংস্থা সমন্বয়ের পক্ষে যুক্তি দেয়। এর সুপারিশ ও ব্যাখ্যাগুলোকে সম্পাদকীয় মতামত হিসেবে চিহ্নিত রাখতে হবে।","evidence":"Editorial text","flag":"Opinion","documentId":"","otherDate":"","url":"https://www.thedailystar.net/opinion/editorial/news/why-cant-we-stop-illegal-sand-mining-4017971","alternateUrl":"","notes":"Linked news reports should become separate records if collected. An editorial is not independent confirmation of the underlying incidents.","id":"BSW-008","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.509Z"}','2026-10-11T22:32:05.509Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-009','https://theclimatewatch.com/teesta-river-dries-up-threatening-northern-livelihoods/',NULL,'{"type":"Context","source":"The Climate Watch","title":"Teesta river dries up, threatening northern livelihoods","date":"2026-01-01","dateKind":"Published","district":"Nilphamari; Lalmonirhat; Rangpur","river":"Teesta; Dimla; Hatibandha","material":"Sand","topics":"Water scarcity; erosion; extraction; river management","language":"English","en":"A broader Teesta livelihoods report includes allegations that mechanized sand extraction worsens erosion. Retain it as contextual coverage because water-sharing, floods, and river management occupy much of the article.","bn":"তিস্তার জীবিকা নিয়ে বিস্তৃত প্রতিবেদনে যান্ত্রিক বালু উত্তোলনে ভাঙন বাড়ার অভিযোগ রয়েছে। পানি বণ্টন, বন্যা ও নদী ব্যবস্থাপনা আলোচনার বড় অংশ হওয়ায় এটিকে প্রাসঙ্গিক পটভূমির প্রতিবেদন হিসেবে রাখা হয়েছে।","evidence":"Article text","flag":"Context","documentId":"","otherDate":"","url":"https://theclimatewatch.com/teesta-river-dries-up-threatening-northern-livelihoods/","alternateUrl":"","notes":"Include secondary extraction coverage, but distinguish it from an extraction incident report.","id":"BSW-009","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.593Z"}','2026-10-11T22:32:05.593Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-010','https://jied.lse.ac.uk/articles/10.31389/jied.149','10.31389/jied.149','{"type":"Research","source":"LSE Press / JIED","title":"Legal and Illicit Sand Mining Practice in Bangladesh: Exploring Supply Chain and its Value","date":"2022-09-28","dateKind":"Published","district":"Multiple","river":"Meghna; Brahmaputra; Jinjiram","material":"Sand","topics":"Supply chains; value addition; community perceptions","language":"English","en":"Bari and Haque compare supply chains, value addition, and community perceptions across three river basins using surveys and interviews. The paper differentiates legal and illicit extraction settings and discusses policy implications.","bn":"বারী ও হক তিনটি নদী অববাহিকায় জরিপ ও সাক্ষাৎকারের মাধ্যমে সরবরাহশৃঙ্খল, মূল্য সংযোজন ও স্থানীয় মানুষের ধারণা তুলনা করেন। গবেষণাটি বৈধ ও অবৈধ উত্তোলনের প্রেক্ষাপট পৃথক করে নীতিগত তাৎপর্য আলোচনা করে।","evidence":"Publisher page; abstract and article text available","flag":"Check study scope","documentId":"10.31389/jied.149","otherDate":"","url":"https://jied.lse.ac.uk/articles/10.31389/jied.149","alternateUrl":"https://www.econstor.eu/handle/10419/320646","notes":"EconStor is the same scholarly work, confirmed by DOI. Count one work and preserve the repository as an alternate source. Pilot summary is based on the abstract, not a full critical appraisal.","id":"BSW-010","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.684Z"}','2026-10-11T22:32:05.684Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-011','https://onlinelibrary.wiley.com/doi/full/10.1002/jid.3966','10.1002/jid.3966','{"type":"Research","source":"Wiley Online Library","title":"Sand Mining, Non-Farm Employment and a Local Labour Force in Rural Bangladesh","date":"2024-11-14","dateKind":"First online","district":"Jamalpur","river":"Brahmaputra","material":"Sand","topics":"Employment; livelihoods; mechanization","language":"English","en":"Hatlebakk, Rahman, and Suykens examine sand mining as a source of livelihood diversification near Jamalpur. The abstract describes a largely local workforce and discusses how mechanization may affect sand workers.","bn":"হাটলেবাক, রহমান ও সুইকেন্স জামালপুরের কাছে জীবিকার বহুমুখীকরণে বালু উত্তোলনের ভূমিকা পরীক্ষা করেন। সারসংক্ষেপে প্রধানত স্থানীয় শ্রমশক্তি এবং যান্ত্রিকীকরণ শ্রমিকদের ওপর কী প্রভাব ফেলতে পারে তা আলোচনা করা হয়েছে।","evidence":"Abstract and publication metadata","flag":"Abstract only","documentId":"10.1002/jid.3966","otherDate":"2025-03-01","url":"https://onlinelibrary.wiley.com/doi/full/10.1002/jid.3966","alternateUrl":"","notes":"Online date is 2024; issue metadata is March 2025. Do not count these as separate publications. Full article was not reviewed.","id":"BSW-011","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.775Z"}','2026-10-11T22:32:05.775Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-012','https://onlinelibrary.wiley.com/doi/10.1111/sjtg.70064','10.1111/sjtg.70064','{"type":"Research","source":"Wiley Online Library","title":"Morpho-ecological changes and socioeconomic impacts due to sand mining in the Someshwari River, Bangladesh","date":"2026-03-03","dateKind":"First online","district":"Netrokona","river":"Someshwari","material":"Sand","topics":"Channel change; environmental impacts; livelihoods","language":"English","en":"This study combines remote sensing, field and laboratory measurements, and social research to examine extraction impacts on the Someshwari. Its abstract reports channel changes, pollution indicators, and livelihood concerns.","bn":"গবেষণাটি সোমেশ্বরীতে উত্তোলনের প্রভাব পরীক্ষা করতে দূর অনুধাবন, মাঠ ও পরীক্ষাগারের পরিমাপ এবং সামাজিক গবেষণা একত্র করে। সারসংক্ষেপে নদীর পরিবর্তন, দূষণের সূচক ও জীবিকা নিয়ে উদ্বেগের কথা রয়েছে।","evidence":"Abstract and publication metadata","flag":"Abstract only","documentId":"10.1111/sjtg.70064","otherDate":"2026-05-01","url":"https://onlinelibrary.wiley.com/doi/10.1111/sjtg.70064","alternateUrl":"","notes":"First online date differs from the May 2026 issue date. Numerical findings were not independently checked and are not extracted into structured fields.","id":"BSW-012","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.886Z"}','2026-10-11T22:32:05.886Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-013','https://www.cmi.no/projects/2512-the-political-economy-of-river-sand-mining-in-south-asia-a-commodity-chain-approach',NULL,'{"type":"Project","source":"Chr. Michelsen Institute","title":"The political economy of river sand mining in South Asia","date":"","dateKind":"Page date not stated","district":"Bangladesh; regional study","river":"Ganga–Brahmaputra–Meghna basin","material":"Sand","topics":"Governance; power; labor; livelihoods","language":"English","en":"CMI describes a project examining sand governance in Bangladesh, India, and Nepal through fieldwork and household surveys. It studies power, capital, labor, and livelihoods and provides links to related outputs.","bn":"সিএমআইয়ের প্রকল্পটি মাঠকাজ ও পারিবারিক জরিপের মাধ্যমে বাংলাদেশ, ভারত ও নেপালে বালু ব্যবস্থাপনা পরীক্ষা করে। এতে ক্ষমতা, পুঁজি, শ্রম ও জীবিকা আলোচনার পাশাপাশি সংশ্লিষ্ট গবেষণার সংযোগ রয়েছে।","evidence":"Project description","flag":"Project date","documentId":"","otherDate":"","url":"https://www.cmi.no/projects/2512-the-political-economy-of-river-sand-mining-in-south-asia-a-commodity-chain-approach","alternateUrl":"","notes":"Timeframe August 2020–October 2023 is the project period, not a verified publication date. Linked publications need individual records and DOI checks.","id":"BSW-013","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:05.993Z"}','2026-10-11T22:32:05.993Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-014','https://bdlaws.minlaw.gov.bd/act-print-1066.html',NULL,'{"type":"Law","source":"Laws of Bangladesh","title":"বালুমহাল ও মাটি ব্যবস্থাপনা আইন, ২০১০","date":"","dateKind":"Act year 2010; consolidated text","district":"National","river":"National jurisdiction","material":"Sand; soil","topics":"Leasing; restrictions; administration; enforcement","language":"Bangla","en":"The official consolidated law sets out the framework for balumahal management, extraction restrictions, leasing, and enforcement. Amendment annotations show that this page incorporates later changes and is not the original 2010 text alone.","bn":"সরকারি সংকলিত আইনে বালুমহাল ব্যবস্থাপনা, উত্তোলনের বিধিনিষেধ, ইজারা ও প্রয়োগের কাঠামো রয়েছে। সংশোধনীর টীকা দেখায় যে এতে পরবর্তী পরিবর্তনও যুক্ত হয়েছে। এটি কেবল ২০১০ সালের মূল পাঠ নয়।","evidence":"Official consolidated HTML text","flag":"Version","documentId":"Act 62 of 2010","otherDate":"","url":"https://bdlaws.minlaw.gov.bd/act-print-1066.html","alternateUrl":"","notes":"First act-details scrape was garbled. Print view recovered readable text. The page''s current print date must not become the law''s enactment date.","id":"BSW-014","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:06.079Z"}','2026-10-11T22:32:06.079Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-015','https://bdlaws.minlaw.gov.bd/act-print-1453.html',NULL,'{"type":"Law","source":"Laws of Bangladesh","title":"বালুমহাল ও মাটি ব্যবস্থাপনা (সংশোধন) আইন, ২০২৩","date":"2023-09-18","dateKind":"Act date","district":"National","river":"National jurisdiction","material":"Sand; soil","topics":"Amendment; leasing; extraction restrictions","language":"Bangla","en":"The official 2023 amendment changes provisions of the 2010 balumahal law, including extraction restrictions, leasing arrangements, and administrative powers. Keep this amendment linked to the consolidated law as a distinct legal instrument.","bn":"সরকারি ২০২৩ সালের সংশোধনীতে ২০১০ সালের বালুমহাল আইনের উত্তোলনের বিধিনিষেধ, ইজারা ও প্রশাসনিক ক্ষমতাসহ বিভিন্ন বিধান পরিবর্তিত হয়েছে। এটিকে সংকলিত আইনের সঙ্গে যুক্ত পৃথক আইনগত দলিল হিসেবে রাখতে হবে।","evidence":"Official amendment HTML text","flag":"Legal detail","documentId":"Act 35 of 2023","otherDate":"","url":"https://bdlaws.minlaw.gov.bd/act-print-1453.html","alternateUrl":"","notes":"Linked to BSW-014. Detailed legal interpretation is outside this collection pilot.","id":"BSW-015","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:06.160Z"}','2026-10-11T22:32:06.160Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-016','https://minland.gov.bd/pages/notices/6940363835ce18e1c058289c',NULL,'{"type":"Rules","source":"Ministry of Land","title":"বালুমহাল ও মাটি ব্যবস্থাপনা বিধিমালা, ২০২৫","date":"2025-11-24","dateKind":"Notification issued; notice posted","district":"National","river":"National jurisdiction","material":"Sand; soil","topics":"Rules; surveying; definitions; leasing","language":"Bangla","en":"The Ministry notice links to the 2025 balumahal rules. The PDF opening identifies SRO 453-Law/2025, issued November 24, with a November 26 gazette heading. Only the first four of 35 pages were parsed.","bn":"মন্ত্রণালয়ের নোটিশে ২০২৫ সালের বালুমহাল বিধিমালার সংযোগ রয়েছে। পিডিএফের শুরুতে এসআরও ৪৫৩-আইন/২০২৫, ২৪ নভেম্বর জারির তারিখ এবং ২৬ নভেম্বরের গেজেট শিরোনাম পাওয়া যায়। ৩৫ পাতার প্রথম চারটি পার্স করা হয়েছে।","evidence":"Official notice; PDF pages 1–4 of 35","flag":"OCR","documentId":"SRO 453-Law/2025","otherDate":"2025-11-26","url":"https://minland.gov.bd/pages/notices/6940363835ce18e1c058289c","alternateUrl":"https://objectstorage.ap-dcc-gazipur-1.oraclecloud15.com/n/axvjbnqprylg/b/V2Ministry/o/office-minland/2024/12/ad7c9ff27078467ca2404e5ffbb07613.pdf","notes":"OCR is readable at the beginning but degrades on later parsed pages. Do not infer commencement or summarize unread rules. Effective date remains unverified. A separate laws listing is a possible mirror.","id":"BSW-016","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:06.258Z"}','2026-10-11T22:32:06.258Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-017','https://sunamganj.gov.bd/pages/notices/6971d87435ce18e1c05e054f',NULL,'{"type":"Lease","source":"Sunamganj district administration","title":"১৪৩৩ বঙ্গাব্দে বালুমহাল ইজারার জন্য উন্মুক্ত দরপত্র বিজ্ঞপ্তি","date":"2026-01-20","dateKind":"Notice posted","district":"Sunamganj","river":"Sunamganj balumahal lease areas","material":"Sand","topics":"Tender; leasing; district administration","language":"Bangla","en":"The district portal advertises an open tender for balumahal leases for Bangla year 1433. The linked PDF contains a schedule and lease-area table, but extraction errors prevent reliable transcription of dates and amounts.","bn":"জেলা পোর্টালে ১৪৩৩ বঙ্গাব্দের বালুমহাল ইজারার উন্মুক্ত দরপত্র বিজ্ঞপ্তি রয়েছে। সংযুক্ত পিডিএফে সময়সূচি ও ইজারার এলাকার তালিকা আছে। পাঠোদ্ধারের ত্রুটির কারণে তারিখ ও অর্থ নির্ভরযোগ্যভাবে প্রতিলিপি করা যায়নি।","evidence":"Official notice; PDF pages 1–2 of 4","flag":"OCR","documentId":"","otherDate":"","url":"https://sunamganj.gov.bd/pages/notices/6971d87435ce18e1c05e054f","alternateUrl":"https://objectstorage.ap-dcc-gazipur-1.oraclecloud15.com/n/axvjbnqprylg/b/V2Ministry/o/office-sunamganj/2024/12/8cb4dd1037f344dc8a7328deb4eb8337.pdf","notes":"Use portal posting date. PDF extraction includes impossible dates and corrupted names. Lease prices, acreage, award outcomes, and tender deadlines remain unverified.","id":"BSW-017","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:32:06.373Z"}','2026-10-11T22:32:06.373Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-51bd004f934d0afb','https://www.tbsnews.net/bangladesh/court/writ-challenges-approval-sand-extraction-matarbari-port-road-project-1464661',NULL,'{"type":"News","source":"The Business Standard","title":"Writ challenges approval for sand extraction for Matarbari port road project","date":"2026-06-16","dateKind":"Published","district":"Cox''s Bazar","river":"Maheshkhali channel; Matarbari","material":"Sand","topics":"Coastal extraction; port construction; court petition; pricing; environmental concerns","language":"English","en":"A lawyer filed a writ petition challenging approval and pricing arrangements for sand extraction for a road to Matarbari port. The report describes concerns raised by environmental organizations and allegations about revenue loss. Filing the petition does not establish a court ruling on those claims.","bn":"মাতারবাড়ী বন্দরের সড়কের জন্য বালু উত্তোলনের অনুমোদন ও মূল্য নির্ধারণ নিয়ে এক আইনজীবী রিট করেন। প্রতিবেদনে পরিবেশ সংগঠনগুলোর উদ্বেগ এবং রাজস্ব ক্ষতির অভিযোগ উঠে আসে। রিট দাখিল করা মানে এসব দাবির ওপর আদালতের রায় হয়েছে, এমন নয়।","evidence":"Article text and publication metadata","flag":"Verify petition and legal references","documentId":"","otherDate":"2026-06-16","url":"https://www.tbsnews.net/bangladesh/court/writ-challenges-approval-sand-extraction-matarbari-port-road-project-1464661","alternateUrl":"","notes":"The petition and administrative approval were not independently retrieved. Do not treat reported pricing, extraction volumes, or predicted impacts as verified measurements.","id":"BSW-51bd004f934d0afb","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T22:33:01.751Z"}','2026-10-11T22:33:01.751Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-267b40635d436859','https://www.prothomalo.com/bangladesh/district/%E0%A6%85%E0%A6%AC%E0%A7%88%E0%A6%A7%E0%A6%AD%E0%A6%BE%E0%A6%AC%E0%A7%87-%E0%A6%A8%E0%A6%A6%E0%A7%80-%E0%A6%A5%E0%A7%87%E0%A6%95%E0%A7%87-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%8B%E0%A6%B2%E0%A6%A8-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%AC%E0%A7%8D%E0%A6%AF%E0%A6%AC%E0%A6%B8%E0%A6%BE%E0%A7%9F%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9C%E0%A6%B0%E0%A6%BF%E0%A6%AE%E0%A6%BE%E0%A6%A8%E0%A6%BE',NULL,'{"type":"News","source":"Prothom Alo","title":"অবৈধভাবে নদী থেকে বালু উত্তোলন, বালু ব্যবসায়ীকে জরিমানা","date":"2021-08-17","dateKind":"Published","district":"Rajbari","river":"Padma branch; Goalanda; Debgram","material":"Sand","topics":"Extraction; mobile court; equipment seizure; enforcement","language":"Bangla","en":"The report describes a mobile-court operation in Goalanda, Rajbari, in which a dredger was seized and a sand trader fined under the balumahal law. It also reports allegations of prolonged unauthorized extraction and political influence. The underlying court record was not collected.","bn":"রাজবাড়ীর গোয়ালন্দে ভ্রাম্যমাণ আদালতের অভিযানে খননযন্ত্র জব্দ ও বালুমহাল আইনে এক বালু ব্যবসায়ীকে জরিমানার কথা প্রতিবেদনে রয়েছে। দীর্ঘদিন অনুমতি ছাড়া উত্তোলন ও রাজনৈতিক প্রভাবের অভিযোগও উঠে আসে। মূল আদালতের নথি সংগ্রহ করা হয়নি।","evidence":"Bangla article text; visible publication date","flag":"Verify enforcement record","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/%E0%A6%85%E0%A6%AC%E0%A7%88%E0%A6%A7%E0%A6%AD%E0%A6%BE%E0%A6%AC%E0%A7%87-%E0%A6%A8%E0%A6%A6%E0%A7%80-%E0%A6%A5%E0%A7%87%E0%A6%95%E0%A7%87-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%8B%E0%A6%B2%E0%A6%A8-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%AC%E0%A7%8D%E0%A6%AF%E0%A6%AC%E0%A6%B8%E0%A6%BE%E0%A7%9F%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9C%E0%A6%