INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-a9d2d0b17595f84d','https://bonikbarta.com/bangladesh/I7goo2LKqCVKE01Q',NULL,'{"type":"News","source":"Bonik Barta","title":"সিলেটে যৌথ অভিযানে ৩৯ ট্রাক্টর পাথর জব্দ, আটক ৬ | বণিক বার্তা","date":"2026-03-20","dateKind":"Published","district":"Sylhet","river":"Shah Arefin Tila; Companiganj; border area","material":"Stone; gravel; sand","topics":"Enforcement; quarrying; equipment seizure","language":"Bangla","en":"The report describes a joint BGB, administration, and police operation against extraction near Shah Arefin Tila. Officials reported seized machinery and materials and detained several people.","bn":"শাহ আরেফিন টিলার কাছে উত্তোলনের বিরুদ্ধে বিজিবি, প্রশাসন ও পুলিশের যৌথ অভিযানের বিবরণ রয়েছে। কর্মকর্তারা যন্ত্র ও উপাদান জব্দ এবং কয়েকজনকে আটকের কথা জানান।","evidence":"Article text and source date label","flag":"Check seizure counts and enforcement record","documentId":"","otherDate":"","url":"https://bonikbarta.com/bangladesh/I7goo2LKqCVKE01Q","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Headline and body give different tractor counts; those quantities are not transcribed into structured fields.","id":"BSW-a9d2d0b17595f84d","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:04.652Z"}','2026-10-11T23:19:04.652Z');
