INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-f0febb9bc2c2db08','https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2024RG000868','10.1029/2024rg000868','{"type":"Research","source":"AGU / Reviews of Geophysics","title":"River Sand and Gravel Mining: Global Drivers, Impacts, and Pathways for Sustainable Management","date":"2026-07-20","dateKind":"First online","district":"Bangladesh; global","river":"Bangladesh rivers; global river systems","material":"Sand; gravel","topics":"Global review; sediment budgets; impacts; management","language":"English","en":"This review synthesizes global sand and gravel extraction research, including Bangladesh cases. It examines sediment budgets, physical and social impacts, monitoring gaps, and pathways for sustainable management.","bn":"বাংলাদেশের উদাহরণসহ বিশ্বব্যাপী বালু ও নুড়ি উত্তোলনের গবেষণা সংকলন করেছে পর্যালোচনাটি। পলির হিসাব, ভৌত ও সামাজিক প্রভাব, পর্যবেক্ষণের ঘাটতি ও টেকসই ব্যবস্থাপনা আলোচনা করা হয়েছে।","evidence":"Publisher/institutional abstract, highlights and publication metadata","flag":"Research interpretation and publication dates need review","documentId":"10.1029/2024RG000868","otherDate":"","url":"https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2024RG000868","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Issue metadata gives 2026/09/01; the first-online date is retained separately.","id":"BSW-f0febb9bc2c2db08","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:04.824Z"}','2026-10-11T23:19:04.824Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-6800bb2987aeedd8','https://news.illinois.edu/study-documents-conflict-between-commerce-and-conservation-at-mining-operation-in-bangladesh/',NULL,'{"type":"News","source":"University of Illinois News Bureau","title":"Study documents conflict between commerce and conservation at mining operation in Bangladesh – News Bureau","date":"2026-03-11","dateKind":"Published","district":"Sylhet","river":"Lubha; Lubhachorra","material":"Gravel; sand","topics":"Research communication; recovery; livelihoods","language":"English","en":"The university reports on a Lubha River study combining satellite imagery and interviews. It contrasts reported river recovery after mining ceased with continuing economic hardship and discusses management recommendations.","bn":"উপগ্রহচিত্র ও সাক্ষাৎকারভিত্তিক লুভা নদীর গবেষণা নিয়ে বিশ্ববিদ্যালয়ের সংবাদটি লেখা। উত্তোলন বন্ধের পর নদীর পুনরুদ্ধারের বিপরীতে অর্থনৈতিক সংকট এবং ব্যবস্থাপনার সুপারিশ আলোচনা করা হয়েছে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://news.illinois.edu/study-documents-conflict-between-commerce-and-conservation-at-mining-operation-in-bangladesh/","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-6800bb2987aeedd8","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:04.911Z"}','2026-10-11T23:19:04.911Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-fc1700319dd2ef3f','https://www.thedailystar.net/news/stop-illegal-sand-mining-padma-4079621',NULL,'{"type":"Editorial","source":"The Daily Star","title":"Stop illegal sand mining from Padma","date":"2026-01-13","dateKind":"Updated","district":"Kushtia","river":"Padma; Daulatpur; Bheramara","material":"Sand","topics":"Enforcement; political influence; court restrictions","language":"English","en":"The editorial calls for coordinated enforcement against Padma extraction and investigation of alleged protection by influential groups. Its ecological and governance arguments remain opinion based on reported concerns.","bn":"পদ্মায় উত্তোলনের বিরুদ্ধে সমন্বিত অভিযান এবং প্রভাবশালী গোষ্ঠীর সুরক্ষার অভিযোগ তদন্তের দাবি জানিয়েছে সম্পাদকীয়টি। পরিবেশ ও ব্যবস্থাপনার যুক্তিগুলো প্রতিবেদিত উদ্বেগভিত্তিক মতামত।","evidence":"Article text and source date label","flag":"Original publication date unverified; review claims","documentId":"","otherDate":"","url":"https://www.thedailystar.net/news/stop-illegal-sand-mining-padma-4079621","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Only an update date is provided; the original publication date remains unverified. Editorial opinion, not independent confirmation of incidents. Underlying court instrument has not been independently collected.","id":"BSW-fc1700319dd2ef3f","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.069Z"}','2026-10-11T23:19:05.069Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-2e0d6f7dfe0aa400','https://www.sciencedirect.com/science/article/pii/S2949790625003015','10.1016/j.crsus.2025.100605','{"type":"Research","source":"Cell Press / ScienceDirect","title":"From extraction to recovery: Geomorphic and social transformations of gravel mining, Lubha River, Northeast Bangladesh","date":"2026-01-05","dateKind":"First online","district":"Sylhet","river":"Lubha; Lubhachorra","material":"Gravel; sand","topics":"Geomorphic change; recovery; livelihoods; mining ban","language":"English","en":"This mixed-methods study combines satellite analysis and interviews to examine gravel extraction and recovery after restrictions. It reports different recovery patterns in the active channel and floodplain and describes livelihood hardship.","bn":"গবেষণাটি উপগ্রহ বিশ্লেষণ ও সাক্ষাৎকারের মাধ্যমে নুড়ি উত্তোলন এবং বিধিনিষেধের পর পুনরুদ্ধার পরীক্ষা করে। সক্রিয় নদী ও প্লাবনভূমির ভিন্ন পুনরুদ্ধার এবং জীবিকার সংকট তুলে ধরা হয়েছে।","evidence":"Publisher/institutional abstract, highlights and publication metadata","flag":"Research interpretation and publication dates need review","documentId":"10.1016/j.crsus.2025.100605","otherDate":"","url":"https://www.sciencedirect.com/science/article/pii/S2949790625003015","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Issue metadata gives 2026/01/23; the first-online date is retained separately.","id":"BSW-2e0d6f7dfe0aa400","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.145Z"}','2026-10-11T23:19:05.145Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-246f82fda6796fdb','https://www.sciencedirect.com/science/article/pii/S2590252026001972','10.1016/j.cacint.2026.100490','{"type":"Research","source":"Elsevier / ScienceDirect","title":"Sand mining''s hidden footprint: Multi-signal landscape change around extraction sites on the Ghaghat, Jamuna, Jamuneshwari, Karatoya and Talma rivers of Bangladesh","date":"2026-10-08","dateKind":"First online","district":"Northern Bangladesh; multiple sites","river":"Ghaghat; Jamuna; Jamuneshwari; Karatoya; Talma","material":"Sand","topics":"Remote sensing; landscape change; attribution; extraction sites","language":"English","en":"The study uses spatial rings and multiple landscape indicators to assess change around five extraction sites. It distinguishes potential mining signals from river-stage variation and broader channel or land-use changes.","bn":"পাঁচটি উত্তোলনস্থলের চারপাশে বলয় ও একাধিক ভূদৃশ্য সূচক দিয়ে পরিবর্তন পরীক্ষা করা হয়েছে। সম্ভাব্য উত্তোলনের প্রভাবকে পানির স্তর এবং নদী বা ভূমি ব্যবহারের অন্যান্য পরিবর্তন থেকে পৃথক করা হয়েছে।","evidence":"Publisher/institutional abstract, highlights and publication metadata","flag":"Research interpretation and publication dates need review","documentId":"10.1016/j.cacint.2026.100490","otherDate":"","url":"https://www.sciencedirect.com/science/article/pii/S2590252026001972","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-246f82fda6796fdb","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.218Z"}','2026-10-11T23:19:05.218Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-bc0803cd4d7b577f','https://researchportal.helsinki.fi/en/publications/social-ecological-resilience-and-environmental-justice-in-banglad/','10.1016/j.exis.2026.102055','{"type":"Research","source":"University of Helsinki Research Portal","title":"Social-ecological resilience and environmental justice in Bangladesh: A multi-site analysis of sand mining governance","date":"2026-10-09","dateKind":"First online","district":"Chandpur; Chattogram; Cox''s Bazar","river":"Chandpur confluence; Sandwip; coastal Cox''s Bazar","material":"Sand","topics":"Governance; environmental justice; livelihoods; leasing","language":"English","en":"This qualitative study examines extraction governance at river-confluence and coastal sites using social-ecological and environmental-justice frameworks. The abstract discusses interviews, unequal burdens, leasing decisions, and institutional coordination.","bn":"নদীর মোহনা ও উপকূলীয় স্থানে উত্তোলনের ব্যবস্থাপনা সামাজিক-পরিবেশগত ও পরিবেশগত ন্যায়বিচারের কাঠামোতে পরীক্ষা করা হয়েছে। সারসংক্ষেপে সাক্ষাৎকার, অসম বোঝা, ইজারা সিদ্ধান্ত ও প্রাতিষ্ঠানিক সমন্বয় আলোচনা করা হয়েছে।","evidence":"Publisher/institutional abstract, highlights and publication metadata","flag":"Research interpretation and publication dates need review","documentId":"10.1016/j.exis.2026.102055","otherDate":"","url":"https://researchportal.helsinki.fi/en/publications/social-ecological-resilience-and-environmental-justice-in-banglad/","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Issue metadata gives 2027/03; the first-online date is retained separately.","id":"BSW-bc0803cd4d7b577f","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.302Z"}','2026-10-11T23:19:05.302Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-e3a8eb122c31cbe5','https://www.prothomalo.com/bangladesh/district/29lxmjsf8h',NULL,'{"type":"News","source":"Prothom Alo","title":"ব্রাহ্মণবাড়িয়ায় অবৈধভাবে বালু উত্তোলনের প্রতিবাদ করায় গুলি, আহত ৬","date":"2026-02-22","dateKind":"Updated","district":"Brahmanbaria","river":"Meghna; Nabinagar; Charlapang","material":"Sand","topics":"Extraction; violence; erosion","language":"Bangla","en":"Residents protesting alleged extraction outside permitted areas were reportedly attacked near Charlapang. The article describes injuries, erosion complaints, and police responses.","bn":"চরলাপাংয়ের কাছে অনুমোদিত এলাকার বাইরে উত্তোলনের প্রতিবাদকারীদের ওপর হামলার কথা প্রতিবেদনে রয়েছে। এতে আহতদের তথ্য, ভাঙনের অভিযোগ ও পুলিশের বক্তব্য তুলে ধরা হয়েছে।","evidence":"Article text and source date label","flag":"Original publication date unverified; review claims","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/29lxmjsf8h","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Only an update date is provided; the original publication date remains unverified. Compare the two same-day Charlapang reports; reported injury counts differ. Each source is kept separately.","id":"BSW-e3a8eb122c31cbe5","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.394Z"}','2026-10-11T23:19:05.394Z');
