INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-3f155d249c4c8f93','https://www.prothomalo.com/bangladesh/9hj9st2fgq',NULL,'{"type":"News","source":"Prothom Alo","title":"সীমিত আকারে পাথর কোয়ারি ইজারা দিতে চায় সরকার","date":"2026-05-07","dateKind":"Published","district":"Sylhet; Sunamganj","river":"Sylhet stone quarries; Bangladesh–India border","material":"Stone; gravel; sand","topics":"Quarry policy; leasing; environmental assessment","language":"Bangla","en":"Officials described plans to consider limited quarry leasing after environmental assessment, excluding ecologically critical areas. A proposed committee would examine sites and court-related restrictions before further decisions.","bn":"প্রতিবেশগত সংকটাপন্ন এলাকা বাদ দিয়ে পরিবেশ মূল্যায়নের পর সীমিত ইজারা বিবেচনার পরিকল্পনার কথা কর্মকর্তারা বলেন। প্রস্তাবিত কমিটি স্থান ও আদালতের বিধিনিষেধ পরীক্ষা করবে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/9hj9st2fgq","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-3f155d249c4c8f93","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.579Z"}','2026-10-11T23:19:05.579Z');
INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-bcdccc782c45360e','https://www.thedailystar.net/opinion/editorial/news/it-time-lawmakers-side-the-rivers-4258186',NULL,'{"type":"Editorial","source":"The Daily Star","title":"Time for lawmakers to side with the rivers","date":"2026-08-28","dateKind":"Updated","district":"Kushtia; Pabna","river":"Padma","material":"Sand","topics":"Governance; political influence; enforcement","language":"English","en":"The editorial argues that political patronage sustains illegal extraction along the Padma despite enforcement. It calls for lawmakers to reject protection of unlawful businesses.","bn":"সম্পাদকীয়তে বলা হয়েছে, অভিযানের পরও রাজনৈতিক পৃষ্ঠপোষকতায় পদ্মায় অবৈধ উত্তোলন টিকে থাকে। বেআইনি ব্যবসার সুরক্ষা বন্ধ করতে আইনপ্রণেতাদের ভূমিকা দাবি করা হয়েছে।","evidence":"Article text and source date label","flag":"Original publication date unverified; review claims","documentId":"","otherDate":"","url":"https://www.thedailystar.net/opinion/editorial/news/it-time-lawmakers-side-the-rivers-4258186","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Only an update date is provided; the original publication date remains unverified. Editorial opinion, not independent confirmation of incidents.","id":"BSW-bcdccc782c45360e","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.660Z"}','2026-10-11T23:19:05.660Z');
