INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-bbd587eca7bda33a','https://www.jagonews24.com/law-courts/news/1101019',NULL,'{"type":"News","source":"Jago News 24","title":"তেঁতুলিয়া নদীতে অবৈধ বালু উত্তোলন বন্ধে লিগ্যাল নোটিশ","date":"2026-03-11","dateKind":"Published","district":"Bhola","river":"Tentulia; Charfassion; Baburhat","material":"Sand","topics":"Legal notice; embankment protection; extraction","language":"Bangla","en":"A lawyer reportedly sent a legal notice seeking an end to extraction near Baburhat and protection of riverbank works. The report describes alleged ecological and infrastructure risks.","bn":"বাবুরহাটের কাছে উত্তোলন বন্ধ ও তীররক্ষা কাজ রক্ষার দাবিতে আইনজীবীর পাঠানো নোটিশের খবর রয়েছে। পরিবেশ ও অবকাঠামোর ঝুঁকির অভিযোগও প্রতিবেদনে উল্লেখ করা হয়েছে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://www.jagonews24.com/law-courts/news/1101019","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-bbd587eca7bda33a","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:16.310Z"}','2026-10-11T23:19:16.310Z');
