INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-ba8798f0bdf14f6a','https://bangla.bdnews24.com/samagrabangladesh/5d62b12c822d',NULL,'{"type":"News","source":"bdnews24.com","title":"যাদুকাটায় বালু উত্তোলন: অভিযোগপত্রে আওয়ামী লীগ নেতারা আসামি, বিএনপি নেতা বাদ","date":"2026-07-07","dateKind":"Published","district":"Sunamganj","river":"Jadukata; Tahirpur; Laurergarh","material":"Sand","topics":"Court proceedings; investigation; political influence","language":"Bangla","en":"The report describes a Department of Environment charge sheet concerning earlier extraction from Jadukata banks. It discusses accused persons included or excluded during the investigation.","bn":"জাদুকাটার পাড় কেটে আগের উত্তোলনের ঘটনায় পরিবেশ অধিদপ্তরের অভিযোগপত্রের খবর রয়েছে। তদন্তে অভিযুক্তদের অন্তর্ভুক্ত বা বাদ দেওয়া নিয়ে আলোচনা করা হয়েছে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://bangla.bdnews24.com/samagrabangladesh/5d62b12c822d","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Underlying court instrument has not been independently collected.","id":"BSW-ba8798f0bdf14f6a","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:17.497Z"}','2026-10-11T23:19:17.497Z');
