INSERT OR IGNORE INTO archive_records(id,canonical_url,doi,data,created_at) VALUES('BSW-8c62cc8a40b87e2d','https://eos.org/editors-vox/the-hidden-costs-of-mining-river-sand',NULL,'{"type":"Context","source":"AGU / Eos","title":"The Hidden Costs of Mining River Sand","date":"2026-07-27","dateKind":"Published","district":"Bangladesh; global","river":"Someshwari; global river systems","material":"Sand; gravel","topics":"Research communication; global impacts; monitoring","language":"English","en":"Authors discuss a global review of sand and gravel mining, including Bangladesh imagery and examples. The article outlines impacts, management concerns, and monitoring needs rather than reporting a new local incident.","bn":"বাংলাদেশের উদাহরণ ও চিত্রসহ বিশ্বব্যাপী বালু-নুড়ি উত্তোলনের পর্যালোচনা আলোচনা করেছেন লেখকেরা। এটি নতুন স্থানীয় ঘটনার বদলে প্রভাব, ব্যবস্থাপনা ও পর্যবেক্ষণের প্রয়োজন তুলে ধরে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://eos.org/editors-vox/the-hidden-costs-of-mining-river-sand","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-8c62cc8a40b87e2d","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:17.658Z"}','2026-10-11T23:19:17.658Z');
